import {UARTReceiver,UARTTransmitter} from './uart-lines.js';
import {poweredDevice,pinVoltage,logic} from './bus-electrical.js';
const format={period:16000000/9600,bits:8,stops:1,parity:null};
function nmea(body){let n=0;for(const c of body)n^=c.charCodeAt(0);return '$'+body+'*'+n.toString(16).toUpperCase().padStart(2,'0')+'\r\n';}
const coordinate=(value,latitude)=>{const v=Math.abs(value),d=Math.floor(v);return String(d).padStart(latitude?2:3,'0')+((v-d)*60).toFixed(4).padStart(7,'0');};
export function attachExpansionUART(runtime,engine,initial){let project=initial,states=new Map(),disposed=false,busy=false;const cpu=runtime.cpu,drives=new Map();
 const drive=(id,pin,value)=>{const k=id+':'+pin;if(drives.get(k)===value)return;drives.set(k,value);commit();};
 const commit=()=>engine.setDrivers('expansion-uart',[...drives].filter(([,v])=>v!==null).map(([endpoint,v])=>({endpoint,voltage:v?3.3:0,ohms:50})));
 const reply=(d,cmd,param=0)=>{const b=[0x7e,0xff,6,cmd,0,param>>8,param&255],sum=-(b.slice(1).reduce((a,b)=>a+b,0))&65535;for(const v of [...b,sum>>8,sum&255,0xef])d.tx.enqueue(v,format);};
 const receive=(d,f)=>{if(f.error||!d.powered)return;d.buffer??=[];if(!d.buffer.length&&f.value!==0x7e)return;d.buffer.push(f.value);if(d.buffer.length!==10)return;const b=d.buffer;d.buffer=[];if(b[9]!==0xef||b[1]!==0xff||b[2]!==6||((b[7]<<8)|b[8])!==(-(b.slice(1,7).reduce((a,b)=>a+b,0))&65535)){d.errors++;return;}const cmd=b[3],v=b[5]*256+b[6];d.commands++;if(cmd===3||cmd===0x12){d.track=v;d.playing=true;}else if(cmd===1){d.track++;d.playing=true;}else if(cmd===2){d.track=Math.max(1,d.track-1);d.playing=true;}else if(cmd===6)d.volume=Math.min(30,v);else if(cmd===0x0e)d.playing=false;else if(cmd===0x0d)d.playing=true;else if(cmd===0x16)d.playing=false;else if(cmd===0x0c){d.playing=false;d.track=1;d.volume=20;}else if(cmd===0x42)reply(d,0x42,d.playing?1:2);else if(cmd===0x43)reply(d,0x43,d.volume);else if(cmd===0x4c)reply(d,0x4c,d.track);else{d.unsupported=cmd;reply(d,0x40,0x40);}if(b[4])reply(d,0x41);drive(d.id,'BUSY',!d.playing);};
 const schedule=d=>{const token=++d.epoch;cpu.addClockEvent(()=>{if(disposed||token!==d.epoch||!d.powered)return;const c=project.components.find(c=>c.id===d.id),lat=c.params.latitude??41.0082,lon=c.params.longitude??28.9784,ns=lat>=0?'N':'S',ew=lon>=0?'E':'W',time='120000.00',a=coordinate(lat,true),b=coordinate(lon,false);const lines=nmea('GPRMC,'+time+',A,'+a+','+ns+','+b+','+ew+',0.00,0.00,191026,,,A')+nmea('GPGGA,'+time+','+a+','+ns+','+b+','+ew+',1,08,0.9,30.0,M,0.0,M,,');for(const v of new TextEncoder().encode(lines))d.tx.enqueue(v,format);d.sentences+=2;schedule(d);},16000000);};
 const refresh=()=>{if(disposed||busy)return;busy=true;try{for(const d of states.values()){const p=poweredDevice(engine.solution,d.id,{min:2.7,max:5.5}),was=d.powered;Object.assign(d,p);if(!d.powered){if(was){d.epoch++;d.tx.cancel();d.rx?.cancel();drive(d.id,'TX',null);drive(d.id,'BUSY',null);}continue;}if(!was){drive(d.id,'TX',true);if(d.type==='gps')schedule(d);else drive(d.id,'BUSY',!d.playing);}d.rx?.observe();}}finally{busy=false;}};
 const update=()=>{const ids=new Set();for(const c of project.components.filter(c=>['gps','dfplayer'].includes(c.type))){ids.add(c.id);if(!states.has(c.id)){const d={id:c.id,type:c.type,powered:false,epoch:0,playing:false,track:1,volume:20,commands:0,errors:0,sentences:0};d.tx=new UARTTransmitter(cpu,value=>drive(c.id,'TX',value));if(c.type==='dfplayer')d.rx=new UARTReceiver(cpu,()=>logic(pinVoltage(engine.solution,c.id,'RX'),3.3),()=>d.powered?format:null,f=>receive(d,f));states.set(c.id,d);}}for(const[id,d]of states)if(!ids.has(id)){d.epoch++;d.tx.cancel();d.rx?.cancel();states.delete(id);for(const p of ['TX','BUSY'])drives.delete(id+':'+p);}refresh();commit();};
 update();const off=engine.subscribe(refresh);return{updateProject(next){project=next;update();},snapshot(){refresh();return{modules:Object.fromEntries([...states].map(([id,d])=>[id,{type:d.type,powered:d.powered,playing:d.playing,track:d.track,volume:d.volume,commands:d.commands,errors:d.errors,unsupported:d.unsupported,sentences:d.sentences}]))};},dispose(){disposed=true;off();for(const d of states.values()){d.epoch++;d.tx.cancel();d.rx?.cancel();}engine.setDrivers('expansion-uart',[]);}};
}
